'use client';
import { useState, useEffect } from 'react';

export default function AdminSponsors() {
  const [sponsors, setSponsors] = useState([]);
  const [formData, setFormData] = useState({ name: '', image_url: '', website_url: '' });

  const fetchSponsors = () => {
    fetch('http://localhost:5001/api/sponsors')
      .then(res => res.json())
      .then(setSponsors);
  };

  useEffect(() => { fetchSponsors(); }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await fetch('http://localhost:5001/api/sponsors', {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(formData)
    });
    setFormData({ name: '', image_url: '', website_url: '' });
    fetchSponsors();
  };

  const deleteSponsor = async (id: number) => {
    await fetch(`http://localhost:5001/api/sponsors/${id}`, { method: 'DELETE' });
    fetchSponsors();
  };

  return (
    <div className="p-10 max-w-4xl mx-auto">
      <h1 className="text-2xl font-black uppercase mb-8">Manage Sponsors</h1>
      
      <form onSubmit={handleSubmit} className="bg-white p-6 rounded-2xl shadow-sm border mb-10 grid grid-cols-1 gap-4">
        <input placeholder="Company Name" className="border p-3 rounded-lg" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
        <input placeholder="Logo Image URL" className="border p-3 rounded-lg" value={formData.image_url} onChange={e => setFormData({...formData, image_url: e.target.value})} />
        <input placeholder="Official Website URL" className="border p-3 rounded-lg" value={formData.website_url} onChange={e => setFormData({...formData, website_url: e.target.value})} />
        <button className="bg-red-600 text-white font-bold py-3 rounded-lg">Add Sponsor</button>
      </form>

      <div className="grid grid-cols-2 gap-4">
        {sponsors.map((s: any) => (
          <div key={s.id} className="border p-4 rounded-xl flex justify-between items-center bg-gray-50">
            <img src={s.image_url} alt={s.name} className="h-10 object-contain grayscale" />
            <button onClick={() => deleteSponsor(s.id)} className="text-red-600 text-xs font-bold uppercase">Remove</button>
          </div>
        ))}
      </div>
    </div>
  );
}